SELECT CASE WHEN d.location IN ('Berlin', 'Bangkok') THEN 'tier_1' ELSE 'other' END AS location_group, CASE WHEN d.budget >= 3505000 THEN 'high' WHEN d.budget >= 1946000 THEN 'mid' ELSE 'low' END AS budget_bucket, MIN(e.salary) AS min_salary FROM employees e JOIN departments d ON d.id = e.dept_id GROUP BY CASE WHEN d.location IN ('Berlin', 'Bangkok') THEN 'tier_1' ELSE 'other' END, CASE WHEN d.budget >= 3505000 THEN 'high' WHEN d.budget >= 1946000 THEN 'mid' ELSE 'low' END
